def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    wall = 8
    wy, wx = np.where(g == wall)
    vertical = len(set(wx.tolist())) == 1
    dot_mask = (g != bg) & (g != wall)
    cols = g[dot_mask]
    dot = int(cols[0]) if len(cols) else 1
    out = g.copy()
    out[dot_mask] = bg
    emit(out.copy(), "Remove every dot; only the 8 wall stays.")
    if vertical:
        c = int(wx[0])
        for y in range(H):
            if g[y, c] != wall:
                continue
            if c - 1 >= 0 and dot_mask[y, :c].any():
                out[y, c - 1] = dot
            if c + 1 < W and dot_mask[y, c + 1:].any():
                out[y, c + 1] = dot
    else:
        r = int(wy[0])
        for x in range(W):
            if g[r, x] != wall:
                continue
            if r - 1 >= 0 and dot_mask[:r, x].any():
                out[r - 1, x] = dot
            if r + 1 < H and dot_mask[r + 1:, x].any():
                out[r + 1, x] = dot
    emit(out.copy(), "Dots on lines that hit a wall cell are pulled against the wall, one per side; dots on gap lines are gone.")
    return out
